"""Eventide Seraph head + rear-hair sheets: python art/characters/sora/f2/gen_heads.py [south north east west]  (ImageGen via the audited bridge; refs = the existing per-direction head reference sheet + the chosen concept direction)"""
import os, subprocess, sys, concurrent.futures as cf
env = dict(os.environ); env['CODEX_BIN'] = r'C:\Program Files\WindowsApps\OpenAI.Codex_26.1111.2228.0_x64__2p2nqsd0c76g0\app\resources\codex.exe'
S = 'art/characters/sora'; D = f'{S}/f2/source'
VIEW = {'south': 'south (front three-quarter)', 'north': 'north (TRUE REAR: back of the head, no face)', 'east': 'east (right-facing profile)', 'west': 'west (left-facing profile)'}
def prompt(d):
    return ("Pixel-art parts sheet for a 2D cutout game rig, %s view. Attached images: (1) a reference sheet, left to right: (A) the existing hero Kai's spiky-haired HEAD piece, (B) his separate REAR HAIR piece that sits behind the head, (C) the character Sora's normal head in this view; all magnified 4x with nearest-neighbour on magenta; (2) a design sheet of Sora's final form 'Eventide Seraph': the LEFT figure (Design A) is the target hair design.\n"
            "Draw exactly TWO pieces for Sora's FINAL form Eventide Seraph, in this order left to right: (1) HEAD: the same head as piece C (same face shape, ear, jaw, skin tone, neck stub, outline weight, pixel-block size) with the Design A hair on the head: a sweeping swept-up CREST made of broad separated feather-shaped locks of luminous mother-of-pearl / champagne hair with pale-rose tips and a deeper dusk-violet inner layer, a few forelocks over the brow, longer on one side; eyes glowing pale rose-gold, calm and focused. Size and proportions as piece A (within 15%%). Each lock thick at the root and fully connected to the scalp mass (no floating islands, no hair-thin strands, finest tips 2-3 art pixels wide). Do NOT draw the thin thorn halo or stars. (2) REAR HAIR: the separate hair piece that sits behind the head: a long drifting cluster of 5 to 6 separated feather-shaped pearl locks with rose tips over a dusk-violet mass, flowing down and back, up to 35%% larger than piece B. View: %s - same orientation as the reference pieces. Big chunky pixel blocks like the reference, no finer detail, no anti-aliasing, no gradients. Flat solid magenta #ff00ff background, the two pieces far apart, nothing overlapping or cropped, no labels, no text." % (VIEW[d], VIEW[d]))
def run(d):
    open(f'{D}/{d}-heads-prompt.txt', 'w', encoding='utf-8').write(prompt(d))
    r = subprocess.run([sys.executable, 'scripts/gen-image.py', D, f'{d}-heads', '--img', f'{S}/concept/sov-heads-ref-{d}.png', '--img', f'{D}/concept.png'], capture_output=True, text=True, env=env); return d, r.returncode, r.stdout[-90:]
if __name__ == '__main__':
    with cf.ThreadPoolExecutor(4) as ex:
        for r in ex.map(run, sys.argv[1:] or ['south', 'north', 'east', 'west']): print(r, flush=True)
